DROP TABLE IF EXISTS `customer_payments`;
CREATE TABLE `customer_payments` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `sale_id` int(10) unsigned NOT NULL,   `customer_id` int(10) unsigned DEFAULT NULL,   `amount` decimal(12,2) NOT NULL,   `method` enum('cash','card','return_credit') NOT NULL DEFAULT 'cash',   `notes` varchar(255) DEFAULT NULL,   `user_id` int(10) unsigned DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   KEY `idx_cp_sale` (`sale_id`),   KEY `idx_cp_customer` (`customer_id`),   KEY `idx_cp_created` (`created_at`),   CONSTRAINT `fk_cp_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,   CONSTRAINT `fk_cp_sale` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE CASCADE ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `customers`;
CREATE TABLE `customers` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `name` varchar(100) NOT NULL,   `phone` varchar(30) DEFAULT NULL,   `email` varchar(150) DEFAULT NULL,   `address` varchar(255) DEFAULT NULL,   `notes` text DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   KEY `idx_customers_name` (`name`),   KEY `idx_customers_phone` (`phone`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `expenses`;
CREATE TABLE `expenses` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `name` varchar(150) NOT NULL,   `category` varchar(50) NOT NULL DEFAULT 'General',   `amount` decimal(12,2) NOT NULL,   `expense_date` date NOT NULL,   `notes` varchar(255) DEFAULT NULL,   `user_id` int(10) unsigned DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   KEY `idx_expenses_date` (`expense_date`),   KEY `idx_expenses_category` (`category`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `filename` varchar(190) NOT NULL,   `applied_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   UNIQUE KEY `uq_migrations_filename` (`filename`) ) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
