DROP TABLE IF EXISTS `product_returns`;
CREATE TABLE `product_returns` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `return_no` varchar(20) NOT NULL,   `sale_id` int(10) unsigned NOT NULL,   `customer_id` int(10) unsigned DEFAULT NULL,   `reason` varchar(255) NOT NULL,   `total_value` decimal(12,2) NOT NULL DEFAULT 0.00,   `user_id` int(10) unsigned DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   UNIQUE KEY `uq_returns_no` (`return_no`),   KEY `idx_pr_sale` (`sale_id`),   KEY `idx_pr_customer` (`customer_id`),   KEY `idx_pr_created` (`created_at`),   CONSTRAINT `fk_pr_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,   CONSTRAINT `fk_pr_sale` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `category_id` int(10) unsigned NOT NULL,   `name` varchar(150) NOT NULL,   `description` text DEFAULT NULL,   `barcode` varchar(64) DEFAULT NULL,   `cost_price` decimal(12,2) NOT NULL DEFAULT 0.00,   `selling_price` decimal(12,2) DEFAULT NULL,   `quantity` int(11) NOT NULL DEFAULT 0,   `min_stock` int(11) NOT NULL DEFAULT 3,   `warranty_days` int(11) NOT NULL DEFAULT 0,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),   PRIMARY KEY (`id`),   UNIQUE KEY `uq_products_barcode` (`barcode`),   KEY `idx_products_category` (`category_id`),   KEY `idx_products_name` (`name`),   KEY `idx_products_active` (`is_active`),   CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `refunds`;
CREATE TABLE `refunds` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `refund_no` varchar(20) NOT NULL,   `sale_id` int(10) unsigned NOT NULL,   `customer_id` int(10) unsigned DEFAULT NULL,   `amount` decimal(12,2) NOT NULL,   `reason` varchar(255) NOT NULL,   `method` enum('cash','card') NOT NULL DEFAULT 'cash',   `user_id` int(10) unsigned DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   UNIQUE KEY `uq_refunds_no` (`refund_no`),   KEY `idx_rf_sale` (`sale_id`),   KEY `idx_rf_customer` (`customer_id`),   KEY `idx_rf_created` (`created_at`),   CONSTRAINT `fk_rf_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,   CONSTRAINT `fk_rf_sale` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `repair_parts`;
CREATE TABLE `repair_parts` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `repair_id` int(10) unsigned NOT NULL,   `product_id` int(10) unsigned DEFAULT NULL,   `part_name` varchar(150) NOT NULL,   `quantity` int(11) NOT NULL DEFAULT 1,   `unit_cost` decimal(12,2) NOT NULL DEFAULT 0.00,   `unit_price` decimal(12,2) NOT NULL DEFAULT 0.00,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   KEY `idx_repair_parts_repair` (`repair_id`),   KEY `idx_repair_parts_product` (`product_id`),   CONSTRAINT `fk_repair_parts_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,   CONSTRAINT `fk_repair_parts_repair` FOREIGN KEY (`repair_id`) REFERENCES `repairs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `repair_status_history`;
CREATE TABLE `repair_status_history` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `repair_id` int(10) unsigned NOT NULL,   `status` varchar(20) NOT NULL,   `note` varchar(255) DEFAULT NULL,   `user_id` int(10) unsigned DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   KEY `idx_rsh_repair` (`repair_id`),   CONSTRAINT `fk_rsh_repair` FOREIGN KEY (`repair_id`) REFERENCES `repairs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `repairs`;
CREATE TABLE `repairs` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `ticket_no` varchar(20) NOT NULL,   `customer_id` int(10) unsigned NOT NULL,   `user_id` int(10) unsigned NOT NULL,   `device_type` varchar(50) NOT NULL,   `brand` varchar(50) DEFAULT NULL,   `model` varchar(80) DEFAULT NULL,   `serial_no` varchar(80) DEFAULT NULL,   `problem` text NOT NULL,   `tech_notes` text DEFAULT NULL,   `status` enum('received','diagnosing','repairing','ready','delivered','cancelled') NOT NULL DEFAULT 'received',   `labor_cost` decimal(12,2) NOT NULL DEFAULT 0.00,   `parts_cost` decimal(12,2) NOT NULL DEFAULT 0.00,   `total_cost` decimal(12,2) NOT NULL DEFAULT 0.00,   `paid_amount` decimal(12,2) NOT NULL DEFAULT 0.00,   `received_at` datetime NOT NULL DEFAULT current_timestamp(),   `delivered_at` datetime DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),   PRIMARY KEY (`id`),   UNIQUE KEY `uq_repairs_ticket` (`ticket_no`),   KEY `idx_repairs_customer` (`customer_id`),   KEY `idx_repairs_status` (`status`),   KEY `idx_repairs_created` (`created_at`),   KEY `fk_repairs_user` (`user_id`),   CONSTRAINT `fk_repairs_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON UPDATE CASCADE,   CONSTRAINT `fk_repairs_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `return_items`;
CREATE TABLE `return_items` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `return_id` int(10) unsigned NOT NULL,   `sale_item_id` int(10) unsigned DEFAULT NULL,   `product_id` int(10) unsigned DEFAULT NULL,   `product_name` varchar(150) NOT NULL,   `quantity` int(11) NOT NULL,   `unit_price` decimal(12,2) NOT NULL DEFAULT 0.00,   `line_total` decimal(12,2) NOT NULL DEFAULT 0.00,   PRIMARY KEY (`id`),   KEY `idx_ri_return` (`return_id`),   KEY `idx_ri_sale_item` (`sale_item_id`),   KEY `idx_ri_product` (`product_id`),   CONSTRAINT `fk_ri_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,   CONSTRAINT `fk_ri_return` FOREIGN KEY (`return_id`) REFERENCES `product_returns` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,   CONSTRAINT `fk_ri_sale_item` FOREIGN KEY (`sale_item_id`) REFERENCES `sale_items` (`id`) ON DELETE SET NULL ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sale_items`;
CREATE TABLE `sale_items` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `sale_id` int(10) unsigned NOT NULL,   `product_id` int(10) unsigned DEFAULT NULL,   `product_name` varchar(150) NOT NULL,   `quantity` int(11) NOT NULL,   `unit_price` decimal(12,2) NOT NULL,   `unit_cost` decimal(12,2) NOT NULL DEFAULT 0.00,   `line_total` decimal(12,2) NOT NULL,   `warranty_days` int(11) NOT NULL DEFAULT 0,   `warranty_expires` date DEFAULT NULL,   PRIMARY KEY (`id`),   KEY `idx_sale_items_sale` (`sale_id`),   KEY `idx_sale_items_product` (`product_id`),   KEY `idx_sale_items_warranty` (`warranty_expires`),   CONSTRAINT `fk_sale_items_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,   CONSTRAINT `fk_sale_items_sale` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE CASCADE ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sales`;
CREATE TABLE `sales` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `invoice_no` varchar(20) NOT NULL,   `customer_id` int(10) unsigned DEFAULT NULL,   `user_id` int(10) unsigned NOT NULL,   `subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,   `discount` decimal(12,2) NOT NULL DEFAULT 0.00,   `total` decimal(12,2) NOT NULL DEFAULT 0.00,   `total_cost` decimal(12,2) NOT NULL DEFAULT 0.00,   `paid_amount` decimal(12,2) NOT NULL DEFAULT 0.00,   `payment_method` enum('cash','card','credit','bank_transfer','other') NOT NULL DEFAULT 'cash',   `status` enum('completed','cancelled') NOT NULL DEFAULT 'completed',   `notes` varchar(255) DEFAULT NULL,   `created_at` datetime NOT NULL DEFAULT current_timestamp(),   PRIMARY KEY (`id`),   UNIQUE KEY `uq_sales_invoice` (`invoice_no`),   KEY `idx_sales_customer` (`customer_id`),   KEY `idx_sales_user` (`user_id`),   KEY `idx_sales_created` (`created_at`),   KEY `idx_sales_status` (`status`),   CONSTRAINT `fk_sales_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,   CONSTRAINT `fk_sales_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

